head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "DEPTH": 1,
        "MENU_NAVI": "HOME > 공통",
        "SYSTEM_ID": "1",
        "MENU_ID": "CO",
        "MENU_NM": "공통"
    }, {
        "DEPTH": 2,
        "MENU_NAVI": "HOME > 공통 > 민원",
        "SYSTEM_ID": "1",
        "MENU_ID": "COMC",
        "MENU_NM": "민원"
    }];
    gdlt_jisaMenuList.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_itemTable_0').innerText == '공통'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
